const agentOutputItem = $input.all().find(item => item.json.output);
const webViewLinkItem = $input.all().find(item => item.json.webViewLink);

if (!agentOutputItem || !webViewLinkItem) {
  throw new Error("Missing 'output' or 'webViewLink' in input data.");
}

const agentOutput = agentOutputItem.json.output;
const webViewLink = webViewLinkItem.json.webViewLink;

const parsedJson = JSON.parse(agentOutput.replace(/```json\n|```/g, ""));

parsedJson.webViewLink = webViewLink;

return { json: parsedJson };

